import * as THREE from "three";
const COLORS=[['CZERWONY','#eaa09b'],['ZIELONY','#b8efc7'],['NIEBIESKI','#94bbec'],['ŻÓŁTY','#e8cf82']];
const TASKS={
 interference:{name:'Interferencja kolor–słowo',instruction:'Wybierz kolor liter, ignorując znaczenie słowa. Klawisze 1–4 odpowiadają przyciskom. W treningu są cztery próby; w przebiegu właściwym 20 zrównoważonych prób zgodnych i niezgodnych.',process:'Selektywna uwaga i kontrola konfliktu. Różnica czasu niezgodne minus zgodne ilustruje interferencję. Na wynik wpływa czytanie, widzenie barw i sposób odpowiedzi.',regions:['lh-caudalanteriorcingulate','lh-caudalmiddlefrontal']},
 trails:{name:'Łączenie punktów',instruction:'Część A: łącz liczby rosnąco. Część B: przeplataj liczbę i literę: 1, A, 2, B… Błędny wybór nie przesuwa kolejności. Klikaj, dotykaj lub użyj Tab i Enter. Po części A uruchom część B.',process:'Przeszukiwanie wzrokowe, tempo ruchowe, utrzymanie sekwencji i przełączanie. B minus A jest umownym kosztem przełączania; różne układy punktów także zmieniają czas.',regions:['lh-superiorparietal','lh-rostralmiddlefrontal']},
 fluency:{name:'Fluencja słowna',instruction:'Wpisuj pojedyncze słowa i zatwierdzaj Enterem. Tryb literowy: słowa na P. Kategorialny: zwierzęta. Trening trwa 15 s, przebieg właściwy 60 s. Powtórzenia nie zwiększają liczby. Można zakończyć wcześniej; czas będzie podany.',process:'Wyszukiwanie leksykalne, pamięć semantyczna, inicjowanie i kontrola odpowiedzi. Brak walidacji słownikowej i norm; trafność słów kategorialnych oceń samodzielnie.',regions:['lh-parsopercularis','lh-middletemporal','lh-rostralmiddlefrontal']},
 sorting:{name:'Przełączanie reguł sortowania',instruction:'Dopasuj bodziec do jednej z trzech kart według koloru, kształtu lub liczby. Trening podaje regułę. W 18 próbach właściwych odkryj ją na podstawie informacji zwrotnej; po kilku próbach reguła się zmienia. Klawisze 1–3 wybierają kartę.',process:'Uczenie reguły z informacji zwrotnej, elastyczność i pamięć robocza. Błędy perseveracyjne oznaczają odpowiedź zgodną z poprzednią, już nieaktualną regułą. To własne bodźce i procedura, bez norm klasycznego testu.',regions:['lh-rostralmiddlefrontal','lh-caudalanteriorcingulate','lh-caudate']},
};
const POINTS=[[15,18],[74,76],[30,65],[80,25],[54,45],[16,86],[88,53],[47,18],[52,84],[18,43],[73,10],[40,39]];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const average=values=>values.length?values.reduce((a,b)=>a+b,0)/values.length:null;
const ms=value=>value===null?'brak poprawnych prób':Math.round(value)+' ms';
export function createTestsLab(host){
 const root=new THREE.Group();host.scene.add(root);root.visible=false;
 const state={active:false,task:'interference',stage:'instructions',training:true,trained:false,index:0,part:'A',waiting:false,variant:'letter',paused:false};
 const board=document.createElement('section');board.className='tests-board';board.hidden=true;board.setAttribute('aria-label','Obszar zadania');host.canvasHost.append(board);
 let trials=[],records=[],shownAt=0,started=0,blockAt=0,pausedAt=0,words=[],duplicates=0,invalid=0,feedback='',lastTick=-1,results={},path=[];
 function setup(training){state.training=training;state.stage='running';state.index=0;state.part='A';state.waiting=false;state.paused=false;state.summary='';records=[];words=[];duplicates=0;invalid=0;feedback='';path=[];started=blockAt=shownAt=performance.now();
  const count=training?4:state.task==='sorting'?18:20;
  const flags=Array.from({length:count},(_,i)=>i%2===0);for(let i=flags.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[flags[i],flags[j]]=[flags[j],flags[i]];}
  trials=Array.from({length:count},(_,i)=>{const ink=Math.floor(Math.random()*4),congruent=flags[i];return state.task==='interference'?{ink,word:congruent?ink:(ink+1+Math.floor(Math.random()*3))%4,congruent}:{color:Math.floor(Math.random()*3),shape:Math.floor(Math.random()*3),quantity:Math.floor(Math.random()*3),rule:training?0:Math.floor(i/6)};});
  render();
 }
 function cue(){requestAnimationFrame(()=>{if(state.stage==='running')shownAt=performance.now();});}
 function summary(){
  const correct=records.filter(r=>r.correct),rts=correct.map(r=>r.rt),error=records.filter(r=>!r.correct).length,total=performance.now()-started;
  if(state.task==='interference'){const a=average(correct.filter(r=>r.congruent).map(r=>r.rt)),b=average(correct.filter(r=>!r.congruent).map(r=>r.rt));return `<p>Poprawne: ${correct.length} / ${records.length} · błędy: ${error}</p><p>Średni czas poprawnej odpowiedzi: ${ms(average(rts))}</p><p>Zgodne: ${ms(a)} · niezgodne: ${ms(b)}</p><p>Interferencja: ${a===null||b===null?'brak danych':ms(b-a)}</p>`;}
  if(state.task==='trails'){const a=records.find(r=>r.block==='A')?.total,b=records.find(r=>r.block==='B')?.total;return `<p>Część A: ${(a/1000).toFixed(2)} s · część B: ${(b/1000).toFixed(2)} s</p><p>Koszt B − A: ${((b-a)/1000).toFixed(2)} s · błędne kliknięcia: ${error}</p>`;}
  if(state.task==='fluency')return `<p>Różne odpowiedzi: ${words.length} · powtórzenia: ${duplicates} · odrzucone wpisy: ${invalid}</p><p>Czas: ${(total/1000).toFixed(1)} s${total<(state.training?15000:60000)?' · zakończono wcześniej':''}. Słowa kategorialne nie są automatycznie weryfikowane.</p><p>${words.map(escape).join(', ')||'Brak wpisów'}</p>`;
  const switching=correct.filter(r=>r.switching).map(r=>r.rt),stable=correct.filter(r=>!r.switching).map(r=>r.rt),a=average(switching),b=average(stable);return `<p>Poprawne: ${correct.length} / ${records.length} · błędy: ${error}</p><p>Błędy perseveracyjne: ${records.filter(r=>r.perseverative).length}</p><p>Średni RT: ${ms(average(rts))} · koszt po zmianie reguły: ${a===null||b===null?'brak danych':ms(a-b)}</p><p>Koszt porównuje dwie pierwsze próby po zmianie z pozostałymi poprawnymi próbami; ma charakter poglądowy.</p>`;
 }
 function finish(){state.summary=(state.task==='fluency'?`<p>Wariant: ${state.variant==='letter'?'literowy · P':'kategorialny · zwierzęta'}</p>`:'')+summary();state.stage='summary';if(state.training)state.trained=true;else results[state.task]=state.summary;render();}
 function render(resetCue=true){
  const task=TASKS[state.task];document.querySelector('#mode-panel').innerHTML=`<div class="tests-panel"><span class="eyebrow">WŁASNE PARADYGMATY EDUKACYJNE</span><h2>Pracownia testów</h2><label class="lab-field">Zadanie<select id="test-task">${Object.entries(TASKS).map(([id,t])=>`<option value="${id}" ${id===state.task?'selected':''}>${t.name}</option>`).join('')}</select></label><h3>${task.name}</h3><p>${task.instruction}</p>${state.task==='fluency'?`<label class="lab-field">Wariant<select id="test-fluency-kind" ${state.stage==='running'?'disabled':''}><option value="letter" ${state.variant==='letter'?'selected':''}>Literowy · P</option><option value="category" ${state.variant==='category'?'selected':''}>Kategorialny · zwierzęta</option></select></label>`:''}<div class="mode-actions"><button class="secondary-button" data-test-train>Próba treningowa</button><button class="primary-button" data-test-main ${!state.trained?'disabled':''}>Przebieg właściwy</button></div>${state.stage==='running'?'<button class="secondary-button" data-test-pause>Wstrzymaj zadanie</button>':''}${state.stage==='summary'?`<article class="lab-stage"><h3>${state.training?'Podsumowanie treningu':'Podsumowanie zadania'}</h3>${state.summary}${state.training?'<p>Trening nie jest zaliczany do wyniku właściwego.</p>':''}</article>`:''}<button class="secondary-button" data-test-results ${!Object.keys(results).length?'disabled':''}>Wyniki tej sesji</button><p>${task.process}</p><div class="connection-links">${task.regions.map(id=>`<button class="source-link" data-test-atlas="${id}">${host.registry.get(id)?.name||id}</button>`).join('')}</div><p class="lab-science-note">To nie jest standaryzowany test. Własne bodźce, brak norm; wynik nie służy ocenie klinicznej i nie lokalizuje uszkodzenia. Znaczenie mają język, wzrok, sprawność ruchowa, sen i kontekst. Czasy performance.now() zależą także od urządzenia. Wyniki są tylko w pamięci tej strony.</p><a class="source-link" href="https://pmc.ncbi.nlm.nih.gov/articles/PMC4084861/" target="_blank" rel="noopener">Funkcje wykonawcze · źródło</a></div>`;
  if(state.paused){board.innerHTML='<div class="task-card"><h2>Zadanie wstrzymane</h2><p>Czas pauzy nie jest wliczany.</p><button class="primary-button" data-test-resume>Kontynuuj</button></div>';return;}
  if(state.stage!=='running'){board.innerHTML=`<div class="task-card"><span class="eyebrow">${state.stage==='summary'?'UKOŃCZONO':'PRZYGOTOWANIE'}</span><h2>${task.name}</h2><p>${state.stage==='summary'?(state.training?'Trening ukończony. Możesz uruchomić przebieg właściwy.':'Wynik i jego ograniczenia znajdziesz w panelu.'):task.instruction}</p><button class="primary-button" ${state.stage==='summary'?'data-test-main':'data-test-train'}>${state.stage==='summary'?'Rozpocznij przebieg właściwy':'Zacznij od treningu'}</button></div>`;return;}
  const trial=trials[state.index],label=`${state.training?'Trening':'Przebieg właściwy'} · ${state.task==='trails'?'część '+state.part:state.task==='fluency'?'odliczanie':`${state.index+1} / ${trials.length}`}`;
  if(state.task==='interference')board.innerHTML=`<div class="task-card"><p>${label}</p><h2 class="color-stimulus" data-ink="${trial.ink}" style="color:${COLORS[trial.ink][1]}" aria-label="Słowo ${COLORS[trial.word][0]}, kolor ${COLORS[trial.ink][0]}">${COLORS[trial.word][0]}</h2><p>Jaki jest kolor liter?</p><div class="test-answers">${COLORS.map(([name,color],i)=>`<button class="secondary-button" data-test-answer="${i}" style="border-color:${color}">${i+1} · ${name}</button>`).join('')}</div><p class="task-feedback" role="status">${feedback}</p></div>`;
  if(state.task==='trails'){
   const count=state.training?4:12;
   board.innerHTML=state.waiting?'<div class="task-card"><h2>Część B</h2><p>Teraz przeplataj liczbę i literę: 1, A, 2, B…</p><button class="primary-button" data-test-part>Rozpocznij część B</button></div>':`<div class="task-card trail-task"><p>${label} · ${state.index} / ${count}</p><div class="trail-board"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><polyline points="${path.map(i=>POINTS[i].join(',')).join(' ')}" fill="none" stroke="#b8efc7" stroke-width=".7"/></svg>${POINTS.slice(0,count).map(([x,y],i)=>`<button class="trail-node ${i<state.index?'done':''}" data-test-node="${i}" style="left:${x}%;top:${y}%" ${i<state.index?'disabled':''}>${state.part==='A'?i+1:i%2===0?i/2+1:String.fromCharCode(65+(i-1)/2)}</button>`).join('')}</div><p class="task-feedback" role="status">${feedback}</p></div>`;
  }
  if(state.task==='fluency')board.innerHTML=`<div class="task-card"><p>${label}</p><h2>${state.variant==='letter'?'Słowa na P':'Zwierzęta'}</h2><output id="test-countdown" class="task-timer"></output><form id="test-word-form"><label class="lab-field" for="test-word">Jedno słowo</label><input id="test-word" type="text" maxlength="60" autocomplete="off" autocapitalize="off"><button class="primary-button" type="submit">Dodaj słowo</button></form><output id="test-word-count">${words.length} różnych słów</output><p id="test-word-feedback" role="status">${feedback}</p><button class="secondary-button" data-test-finish>Zakończ wcześniej</button></div>`;
  if(state.task==='sorting'){
   const shapes=['●','■','▲'],colors=COLORS.slice(0,3),drawCard=(color,shape,count)=>`<span style="color:${colors[color][1]}">${Array.from({length:count+1},()=>shapes[shape]).join(' ')}</span>`;
   board.innerHTML=`<div class="task-card"><p>${label}</p>${state.training?'<p>Reguła treningu: kolor.</p>':''}<div class="sorting-stimulus" data-color="${trial.color}" data-shape="${trial.shape}" data-quantity="${trial.quantity}">${drawCard(trial.color,trial.shape,trial.quantity)}</div><p>Wybierz kartę docelową</p><div class="sorting-options">${[0,1,2].map(i=>`<button class="secondary-button" data-test-answer="${i}" aria-label="Karta ${i+1}: ${colors[i][0]}, ${['koło','kwadrat','trójkąt'][i]}, liczba ${i+1}">${drawCard(i,i,i)}<small>${i+1}</small></button>`).join('')}</div><p class="task-feedback" role="status">${feedback}</p></div>`;
  }
  if(resetCue)cue();if(state.task==='fluency')document.querySelector('#test-word')?.focus();
 }
 function answer(value){if(state.stage!=='running'||state.paused||!['sorting','interference'].includes(state.task))return;if(value<0||value>=(state.task==='sorting'?3:4))return;const trial=trials[state.index],expected=state.task==='interference'?trial.ink:trial[['color','shape','quantity'][trial.rule]],correct=value===expected;
  records.push({rt:performance.now()-shownAt,correct,congruent:trial.congruent,switching:!state.training&&state.index>=6&&state.index%6<2,perseverative:state.task==='sorting'&&!correct&&trial.rule>0&&value===trial[['color','shape','quantity'][trial.rule-1]]});feedback=correct?'Poprawnie.':'Nietrafna odpowiedź.';state.index++;if(state.index>=trials.length)finish();else render();
 }
 function pause(){if(state.stage!=='running'||state.paused)return;state.paused=true;pausedAt=performance.now();render();}
 function resume(){const elapsed=performance.now()-pausedAt;started+=elapsed;blockAt+=elapsed;shownAt+=elapsed;state.paused=false;render(false);}
 document.addEventListener('click',e=>{if(!state.active)return;const b=e.target.closest('button');if(!b)return;
  if(b.hasAttribute('data-test-train'))setup(true);if(b.hasAttribute('data-test-main')&&state.trained)setup(false);
  if(b.dataset.testAnswer!==undefined)answer(+b.dataset.testAnswer);
  if(b.dataset.testNode!==undefined&&state.task==='trails'&&state.stage==='running'&&!state.paused){const value=+b.dataset.testNode,correct=value===state.index;records.push({correct,rt:performance.now()-shownAt});if(correct){path.push(value);state.index++;shownAt=performance.now();feedback='';}else feedback='Sprawdź kolejność.';if(state.index>=(state.training?4:12)){records.push({correct:true,block:state.part,total:performance.now()-blockAt});if(state.part==='A'){state.part='B';state.index=0;path=[];state.waiting=true;render();}else finish();}else render();}
  if(b.hasAttribute('data-test-part')){state.waiting=false;blockAt=performance.now();render();}
  if(b.hasAttribute('data-test-finish')&&state.task==='fluency')finish();if(b.hasAttribute('data-test-pause'))pause();if(b.hasAttribute('data-test-resume'))resume();if(b.hasAttribute('data-test-results')){pause();host.openDialog('WYNIKI LOKALNE',`<h2>Wyniki tej sesji</h2>${Object.entries(results).map(([id,html])=>`<article class="lab-stage"><h3>${TASKS[id].name}</h3>${html}</article>`).join('')}<p>Ostatni przebieg właściwy każdego zadania. Brak norm i oceny klinicznej. Po odświeżeniu strony wyniki znikną.</p>`);}if(b.dataset.testAtlas){pause();host.describe(b.dataset.testAtlas);}
 });
 document.addEventListener('submit',e=>{if(!state.active||e.target.id!=='test-word-form')return;e.preventDefault();if(state.paused)return;const input=document.querySelector('#test-word'),word=input.value.normalize('NFKC').trim().toLocaleLowerCase('pl');if(!word||!/^[\p{L}-]+$/u.test(word)||(state.variant==='letter'&&!word.startsWith('p'))){invalid++;feedback='Wpisz jedno słowo spełniające warunek.';}else if(words.includes(word)){duplicates++;feedback='To słowo już wystąpiło.';}else{words.push(word);feedback='Dodano.';}input.value='';document.querySelector('#test-word-count').textContent=`${words.length} różnych słów`;document.querySelector('#test-word-feedback').textContent=feedback;});
 document.addEventListener('keydown',e=>{if(!state.active||state.paused||e.repeat||e.target.matches('input,select,textarea')||document.querySelector('#dialog').open)return;if(['1','2','3','4'].includes(e.key)&&state.stage==='running'&&['interference','sorting'].includes(state.task)){e.preventDefault();answer(+e.key-1);}});
 document.addEventListener('change',e=>{if(!state.active)return;if(e.target.id==='test-task'){state.task=e.target.value;state.trained=false;state.stage='instructions';state.paused=false;render();}if(e.target.id==='test-fluency-kind'){state.variant=e.target.value;state.trained=false;render();}});
 document.addEventListener('visibilitychange',()=>{if(state.active&&document.hidden)pause();});
 return{root,state,enter(){state.active=true;root.visible=true;board.hidden=false;document.querySelector('.controls').inert=true;document.querySelector('#world-scale').textContent='Zadania edukacyjne · bez norm';document.querySelector('.viewport-title>div').textContent='Zadania poznawcze';render();},exit(){if(state.stage==='running')pause();state.active=false;root.visible=false;board.hidden=true;},update(dt,t){if(!state.active)return;if(document.querySelector('#dialog').open)pause();host.macroObjects().forEach(m=>m.visible=false);if(state.task==='fluency'&&state.stage==='running'&&!state.paused&&t-lastTick>100){lastTick=t;const remaining=Math.max(0,(state.training?15000:60000)-(performance.now()-started));const output=document.querySelector('#test-countdown');if(output)output.textContent=(remaining/1000).toFixed(1)+' s';if(remaining===0)finish();}}};
}
